import{_ as s,a0 as a,w as p,s as u,ao as r,I as e,x as l,a1 as i,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"解决构建全球社区带来的挑战 | LCTT x X-CMD","titleTemplate":false,"description":"解决构建全球社区带来的挑战 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"解决构建全球社区带来的挑战 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"解决构建全球社区带来的挑战 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20171208 Overcoming challenges when building great global communities","title":"解决构建全球社区带来的挑战","tag":"201806","desc":""},"relativePath":"201806/20171208 Overcoming challenges when building great global communities.md","filePath":"[post].md"}'),d={name:"201806/20171208 Overcoming challenges when building great global communities.md"};function m(g,t,f,T,b,h){const n=a("Link");return p(),u("div",null,[t[19]||(t[19]=r('<h1 id="解决构建全球社区带来的挑战" tabindex="-1">解决构建全球社区带来的挑战 <a class="header-anchor" href="#解决构建全球社区带来的挑战" aria-label="Permalink to “解决构建全球社区带来的挑战”">​</a></h1><blockquote><p>全球开源社区通常面临着语音壁垒、文化差异以及其它的挑战。如何去解决它们呢？</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_community2.png?itok=1blC7-NY" alt="配图 "></p><p>今天的开源组织参与人员来自于全世界。你能预见到组建在线社区可能遇到哪些困难吗？有没有什么办法能够克服这些困难呢？</p><p>为开源社区贡献力量的人共同合作推动软件的开发和发展。在过去，人们是面对面或者通过邮件和电话来交流的。今天，科技孕育出了在线交流——人们只需要进入一个聊天室或消息渠道就能一起工作了。比如，你可以早上跟摩洛哥的人一起工作，到了晚上又跟夏威夷的人一起工作。</p><h3 id="全球社区的三个挑战" tabindex="-1">全球社区的三个挑战 <a class="header-anchor" href="#全球社区的三个挑战" aria-label="Permalink to “全球社区的三个挑战”">​</a></h3><p>任何一个团队合作过的人都知道意见分歧是很难被克服的。对于在线社区来说，语言障碍、不同的时区，以及文化差异也带来了新的挑战。</p><h4 id="语言障碍" tabindex="-1">语言障碍 <a class="header-anchor" href="#语言障碍" aria-label="Permalink to “语言障碍”">​</a></h4><p>英语是开源社区中的主流语言，因此英语不好的人会很难看懂文档和修改意见。为了克服这个问题，吸引其他地区的社区成员，你需要邀请双语者参与到社区中来。问问周围的人——你会发现意想不到的精通其他语言的人。社区的双语成员可以帮助别人跨越语言障碍，并且可以通过翻译软件和文档来扩大项目的受众范围。</p><p>人们使用的编程语言也不一样。你可能喜欢用 Bash 而其他人则可能更喜欢 Python、Ruby、C 等其他语言。这意味着，人们可能由于编程语言的原因而难以为你的代码库做贡献。项目负责人为项目选择一门被软件社区广泛认可的语言至关重要。如果你选择了一门偏门的语言，则很少人能够参与其中。</p><h4 id="不同的时区" tabindex="-1">不同的时区 <a class="header-anchor" href="#不同的时区" aria-label="Permalink to “不同的时区”">​</a></h4><p>时区为开源社区带来了另一个挑战。比如，若你在芝加哥，想与一个在伦敦的成员安排一次视频会议，你需要调整 8 小时的时差。根据合作者的地理位置，你可能要在深夜或者清晨工作。</p><p>肉身转移，可以让你的团队在同一个时区工作可以帮助克服这个挑战，但这种方法只有极少数社区才能够负担的起。我们还可以定期举行虚拟会议讨论项目，建立一个固定的时间和地点以供所有人来讨论未决的事项，即将发布的版本等其他主题。</p><p>不同的时区也可以成为你的优势，因为团队成员可以全天候的工作。若你拥有一个类似 IRC 这样的实时交流平台，用户可以在任意时间都能找到人来回答问题。</p><h4 id="文化差异" tabindex="-1">文化差异 <a class="header-anchor" href="#文化差异" aria-label="Permalink to “文化差异”">​</a></h4><p>文化差异是开源组织面临的最大挑战。世界各地的人都有不同的思考方式、计划以及解决问题的方法。政治环境也会影响工作环境并影响决策。</p><p>作为项目负责人，你应该努力构建一种能包容不同看法的环境。文化差异可以鼓励社区沟通。建设性的讨论总是对项目有益，因为它可以帮助社区成员从不同角度看待问题。不同意见也有助于解决问题。</p><p>要成功开源，团队必须学会拥抱差异。这不简单，但多样性最终会使社区收益。</p><h3 id="加强在线沟通的其他方法" tabindex="-1">加强在线沟通的其他方法 <a class="header-anchor" href="#加强在线沟通的其他方法" aria-label="Permalink to “加强在线沟通的其他方法”">​</a></h3>',19)),e("ul",null,[t[4]||(t[4]=r("<li><strong>本地化：</strong> 在线社区成员可能会发现位于附近的贡献者——去见个面并组织一个本地社区。只需要两个人就能组建一个社区了。可以邀请其他当地用户或雇员参与其中；他们甚至还能为以后的聚会提供场所呢。</li><li><strong>组织活动：</strong> 组织活动是构建本地社区的好方法，而且费用也不高。你可以在当地的咖啡屋或者啤酒厂聚会，庆祝最新版本的发布或者某个核心功能的实现。组织的活动越多，人们参与的热情就越高（即使只是因为单纯的好奇心）。最终，可能会找到一家公司为你提供聚会的场地，或者为你提供赞助。</li><li><strong>保持联系：</strong> 每次活动后，联系本地社区成员。收起电子邮箱地址或者其他联系方式并邀请他们参与到你的交流平台中。邀请他们为其他社区做贡献。你很可能会发现很多当地的人才，运气好的话，甚至可能发现新的核心开发人员！</li><li><strong>分享经验：</strong> 本地社区是一种非常有价值的资源，对你，对其他社区来说都是。与可能受益的人分享你的发现和经验。如果你不清楚（LCTT 译注：这里原文是说 sure，但是根据上下文，这里应该是 not sure）如何策划一场活动或会议，可以咨询其他人的意见。也许能找到一些有经验的人帮你走到正轨。</li><li><strong>关注文化差异：</strong> 记住，文化规范因地点和人而异，因此在清晨安排某项活动可能适用于一个地方的人，但是不合适另一个地方的人。当然，你可以（也应该）利用其他社区的参考资料来更好地理解这种差异性，但有时你也需要通过试错的方式来学习。不要忘了分享你所学到的东西，让别人也从中获益。</li><li><strong>检查个人观点：</strong> 避免在工作场合提出带有很强主观色彩的观点（尤其是与政治相关的观点）。这会抑制开放式的沟通和问题的解决。相反，应该专注于鼓励与团队成员展开建设性讨论。如果你发现陷入了激烈的争论中，那么后退一步，冷静一下，然后再从更加积极的角度出发重新进行讨论。讨论必须是有建设性的，从多个角度讨论问题对社区有益。永远不要把自己的主观观念放在社区的总体利益之前。</li>",6)),e("li",null,[t[1]||(t[1]=e("strong",null,"尝试异步沟通：",-1)),t[2]||(t[2]=l(" 这些天，实时通讯平台已经引起了大家的关注，但除此之外还别忘了电子邮件。如果没有在网络平台上找到人的话，可以给他们发送一封电子邮件。有可能你很快就能得到回复。考虑使用那些专注于异步沟通的平台，比如 ",-1)),i(n,{href:"https://twistapp.com"},{default:o(()=>[...t[0]||(t[0]=[l("Twist",-1)])]),_:1}),t[3]||(t[3]=l("，也不要忘了查看并更新论坛和维基。",-1))]),t[5]||(t[5]=e("li",null,[e("strong",null,"使用不同的解决方案："),l(" 并不存在一个单一的完美的解决方法，学习最有效的方法还是通过经验来学习。从反复试验中你可以学到很多东西。不要害怕失败；你会从失败中学到很多东西从而不停地进步。")],-1))]),t[20]||(t[20]=e("h3",{id:"社区需要营养",tabindex:"-1"},[l("社区需要营养 "),e("a",{class:"header-anchor",href:"#社区需要营养","aria-label":"Permalink to “社区需要营养”"},"​")],-1)),t[21]||(t[21]=e("p",null,"将社区想象成是一颗植物的幼苗。你需要每天给它浇水，提供阳光和氧气。社区也是一样：倾听贡献者的声音，记住你在与活生生的人进行互动，他们需要以合适的方式进行持续的交流。如果社区缺少了人情味，人们会停止对它的贡献。",-1)),t[22]||(t[22]=e("p",null,"最后，请记住，每个社区都是不同的，没有一种单一的解决方法能够适用于所有社区。坚持不断地从社区中学习并适应这个社区。",-1)),t[23]||(t[23]=e("hr",null,null,-1)),e("p",null,[t[7]||(t[7]=l("via: ",-1)),i(n,{href:"https://opensource.com/article/17/12/working-worldwide-communities"},{default:o(()=>[...t[6]||(t[6]=[l("https://opensource.com/article/17/12/working-worldwide-communities",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=l("作者：",-1)),i(n,{href:"https://opensource.com/users/jose"},{default:o(()=>[...t[8]||(t[8]=[l("José Antonio Rey",-1)])]),_:1}),t[12]||(t[12]=l(" 译者：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[9]||(t[9]=[l("lujun9972",-1)])]),_:1}),t[13]||(t[13]=l(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[10]||(t[10]=[l("wxy",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=l("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[l("LCTT",-1)])]),_:1}),t[17]||(t[17]=l(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[l("Linux中国",-1)])]),_:1}),t[18]||(t[18]=l(" 荣誉推出",-1))])])}const w=s(d,[["render",m]]);export{k as __pageData,w as default};
